from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if key present and not expired
            if key in cache:
                v, wt = cache[key]
                if t - wt < ttl:
                    # present, remove for update
                    del cache[key]
                else:
                    # expired, treat as absent
                    del cache[key]
            # now insert
            if key not in cache and len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, t)
            cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t - wt < ttl:
                    results.append(v)
                    cache.move_to_end(key)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)
    return results

